## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/migraineLogic.ts`

```typescript
/**
 * Migraine Clinical Logic Engine
 * Based on: AAN/AHS 2025 CGRP Guidelines, AHS Consensus 2021, AAN 2012 Prevention Guidelines
 * Key decisions: Acute therapy (triptans vs CGRP antagonists vs gepants/ditans),
 *                Preventive therapy (CGRP mAbs vs topiramate vs valproate vs beta-blockers),
 *                Medication overuse headache (MOH) management
 */

export type MigraineFrequency = 'low' | 'moderate' | 'high' | 'chronic';
// low: <4 days/month, moderate: 4–7 days/month, high: 8–14 days/month, chronic: ≥15 days/month

export type AcuteTherapyResponse =
  | 'none_tried'
  | 'triptan_effective'
  | 'triptan_ineffective'
  | 'triptan_contraindicated'
  | 'nsaid_effective'
  | 'nsaid_only';

export type PreventiveTherapyHistory =
  | 'none'
  | 'failed_topiramate'
  | 'failed_valproate'
  | 'failed_beta_blocker'
  | 'failed_amitriptyline'
  | 'failed_2plus_preventives'
  | 'on_cgrp_mab';

export type MigraineSubtype = 'episodic' | 'chronic' | 'menstrual' | 'hemiplegic' | 'vestibular';

export interface MigraineInput {
  migraineSubtype: MigraineSubtype;
  frequency: MigraineFrequency;
  headacheDaysPerMonth: number;
  acuteTherapyResponse: AcuteTherapyResponse;
  preventiveHistory: PreventiveTherapyHistory;
  hasCardiovascularDisease: boolean; // contraindication for triptans
  hasUncontrolledHypertension: boolean;
  hasHemiplegicMigraine: boolean;
  hasBasilarMigraine: boolean;
  isPregnantOrPlanning: boolean;
  hasMOH: boolean; // medication overuse headache (acute meds ≥10–15 days/month)
  acuteMedicationDaysPerMonth: number;
  hasDepression: boolean;
  hasEpilepsy: boolean;
  hasWeightConcerns: boolean; // relevant for topiramate/valproate
  wantsInjectable: boolean;
  age: number;
}

export interface MigraineRecommendation {
  primaryRecommendation: string;
  acuteTherapy: string;
  preventiveTherapy: string;
  recommendedAgents: string[];
  agentsToAvoid: string[];
  mohManagement: string;
  urgentFlags: string[];
  pregnancyConsiderations: string;
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessMigraine(input: MigraineInput): MigraineRecommendation {
  const urgentFlags: string[] = [];
  const agentsToAvoid: string[] = [];
  const recommendedAgents: string[] = [];
  const nextSteps: string[] = [];

  // Red flags
  if (input.headacheDaysPerMonth >= 15) {
    urgentFlags.push('Chronic migraine (≥15 headache days/month): preventive therapy is mandatory');
  }
  if (input.hasMOH || input.acuteMedicationDaysPerMonth >= 10) {
    urgentFlags.push(
      'Medication overuse headache (MOH) suspected: acute medication use ≥10 days/month. ' +
      'Withdrawal and preventive therapy are required before acute therapy can be optimized.'
    );
  }

  // Contraindications
  if (input.hasCardiovascularDisease || input.hasUncontrolledHypertension) {
    agentsToAvoid.push('Triptans (vasoconstrictive — contraindicated in CAD, uncontrolled HTN, stroke history)');
    agentsToAvoid.push('Ergotamines');
  }
  if (input.hasHemiplegicMigraine || input.hasBasilarMigraine) {
    agentsToAvoid.push('Triptans (contraindicated in hemiplegic and basilar migraine)');
    agentsToAvoid.push('Ergotamines');
  }
  if (input.isPregnantOrPlanning) {
    agentsToAvoid.push('Topiramate (teratogenic — Category D)', 'Valproate (teratogenic — Category X)', 'Ergotamines', 'NSAIDs (3rd trimester)');
  }
  if (input.hasEpilepsy) {
    agentsToAvoid.push('Amitriptyline (lowers seizure threshold at high doses)');
  }
  if (input.hasWeightConcerns) {
    agentsToAvoid.push('Valproate (weight gain)', 'Amitriptyline (weight gain)');
  }

  // Acute therapy
  let acuteTherapy = '';
  if (input.hasCardiovascularDisease || input.hasHemiplegicMigraine || input.hasBasilarMigraine) {
    acuteTherapy =
      'Triptan-contraindicated: use gepants (ubrogepant 50–100mg, rimegepant 75mg) or lasmiditan 50–200mg (ditan). ' +
      'NSAIDs + antiemetics (metoclopramide, prochlorperazine) as first-line alternatives. ' +
      'Gepants can also be used as preventive (rimegepant 75mg every other day — FDA approved 2021).';
    recommendedAgents.push('Ubrogepant 50–100mg (acute)', 'Rimegepant 75mg (acute or preventive)', 'Lasmiditan 50–200mg (acute)', 'Naproxen sodium 500–550mg + metoclopramide');
  } else if (input.acuteTherapyResponse === 'triptan_effective') {
    acuteTherapy =
      'Continue effective triptan. Ensure early treatment (within 1 hour of onset). ' +
      'If incomplete response, consider combination triptan + NSAID or switch triptan class.';
    recommendedAgents.push('Current effective triptan (continue)', 'Sumatriptan + naproxen combination tablet');
  } else if (input.acuteTherapyResponse === 'triptan_ineffective' || input.acuteTherapyResponse === 'none_tried') {
    acuteTherapy =
      'Triptans are first-line acute therapy for moderate-severe migraine (AAN Level A). ' +
      'If one triptan fails, trial a different triptan class before declaring class failure. ' +
      'Gepants (ubrogepant, rimegepant) are effective alternatives with no cardiovascular contraindications.';
    recommendedAgents.push(
      'Sumatriptan 50–100mg PO or 6mg SC',
      'Rizatriptan 10mg PO',
      'Eletriptan 40mg PO',
      'Zolmitriptan 2.5–5mg PO or nasal',
      'Ubrogepant 50–100mg (if triptan fails or contraindicated)',
      'Rimegepant 75mg ODT'
    );
  } else {
    acuteTherapy =
      'NSAIDs (naproxen 500mg, ibuprofen 400–800mg) with antiemetic for mild-moderate attacks. ' +
      'Triptans for moderate-severe attacks.';
    recommendedAgents.push('Naproxen sodium 500mg', 'Ibuprofen 400–800mg', 'Sumatriptan 50mg');
  }

  // Preventive therapy
  let preventiveTherapy = '';
  const needsPreventive =
    input.frequency === 'high' ||
    input.frequency === 'chronic' ||
    input.headacheDaysPerMonth >= 4 ||
    input.hasMOH;

  if (needsPreventive) {
    if (input.preventiveHistory === 'failed_2plus_preventives' || input.preventiveHistory === 'failed_topiramate' || input.preventiveHistory === 'failed_valproate') {
      preventiveTherapy =
        'Failed ≥2 oral preventives: CGRP monoclonal antibodies are indicated (AAN/AHS 2025 Level A). ' +
        'Erenumab 70–140mg SC monthly, fremanezumab 225mg SC monthly or 675mg quarterly, ' +
        'galcanezumab 240mg loading then 120mg SC monthly, eptinezumab 100–300mg IV quarterly. ' +
        'All have similar efficacy (~50% responder rate). Select based on administration preference and formulary.';
      recommendedAgents.push(
        'Erenumab 70–140mg SC monthly (anti-CGRP receptor)',
        'Fremanezumab 225mg SC monthly or 675mg quarterly',
        'Galcanezumab 120mg SC monthly (240mg loading dose)',
        'Eptinezumab 100–300mg IV quarterly'
      );
      nextSteps.push('Prior authorization for CGRP mAb', 'Document failure of ≥2 oral preventives', 'Reassess at 3 months (≥50% reduction in headache days = response)');
    } else if (input.preventiveHistory === 'none') {
      if (input.isPregnantOrPlanning) {
        preventiveTherapy =
          'Pregnancy/planning: oral preventives with teratogenic risk are contraindicated. ' +
          'Magnesium glycinate 400mg daily is safest option. ' +
          'Propranolol (low dose) may be considered with OB/GYN guidance. ' +
          'CGRP mAbs: insufficient safety data — generally held during pregnancy.';
        recommendedAgents.push('Magnesium glycinate 400mg daily', 'Propranolol 40–80mg daily (with OB guidance)');
      } else if (input.hasDepression) {
        preventiveTherapy =
          'Migraine with comorbid depression: amitriptyline 10–75mg nightly addresses both conditions. ' +
          'Venlafaxine 75–150mg daily is an alternative (SNRI with migraine prevention evidence). ' +
          'Topiramate and beta-blockers are alternatives if antidepressants not preferred.';
        recommendedAgents.push('Amitriptyline 10–75mg nightly', 'Venlafaxine 75–150mg daily', 'Topiramate 25–100mg daily');
      } else if (input.hasEpilepsy) {
        preventiveTherapy =
          'Migraine with comorbid epilepsy: valproate 500–1500mg/day and topiramate 25–100mg/day have dual indication. ' +
          'Avoid if pregnancy is planned (both teratogenic).';
        recommendedAgents.push('Valproate 500–1500mg/day (if not planning pregnancy)', 'Topiramate 25–100mg/day');
      } else {
        preventiveTherapy =
          'First-line oral preventives: topiramate 25–100mg/day, propranolol 40–160mg/day, metoprolol 50–200mg/day, ' +
          'amitriptyline 10–75mg nightly, or venlafaxine 75–150mg/day (AAN Level A). ' +
          'Select based on comorbidities, tolerability, and patient preference.';
        recommendedAgents.push(
          'Topiramate 25–100mg/day',
          'Propranolol 40–160mg/day',
          'Metoprolol 50–200mg/day',
          'Amitriptyline 10–75mg nightly',
          'Candesartan 8–16mg/day (Level B)'
        );
      }
      nextSteps.push('Trial preventive for minimum 8–12 weeks at therapeutic dose before assessing response', 'Headache diary to track frequency and response');
    } else {
      preventiveTherapy =
        'Prior preventive failure: switch to different class or escalate to CGRP mAb. ' +
        'Document prior failures for insurance prior authorization. ' +
        'CGRP mAbs are indicated after failure of 2 oral preventives.';
      recommendedAgents.push('Trial different oral preventive class', 'Consider CGRP mAb if ≥2 failures documented');
    }
  } else {
    preventiveTherapy = 'Low-frequency migraine (<4 days/month): preventive therapy not currently indicated. Optimize acute therapy.';
  }

  // MOH management
  let mohManagement = 'No medication overuse headache identified.';
  if (input.hasMOH || input.acuteMedicationDaysPerMonth >= 10) {
    mohManagement =
      'Medication overuse headache (MOH): acute medication must be withdrawn. ' +
      'Abrupt withdrawal preferred for triptans, ergotamines, and NSAIDs. ' +
      'Gradual taper for opioids and barbiturates (withdrawal seizure risk). ' +
      'Bridge therapy: naproxen 500mg BID x 2 weeks or prednisone taper during withdrawal. ' +
      'Initiate preventive therapy simultaneously. ' +
      'Warn patient of rebound headache during first 2 weeks of withdrawal. ' +
      'Inpatient detoxification for severe cases or opioid/barbiturate overuse.';
    urgentFlags.push('MOH: acute medication withdrawal required before preventive therapy can be effective');
  }

  // Pregnancy considerations
  let pregnancyConsiderations = 'No pregnancy-specific restrictions identified.';
  if (input.isPregnantOrPlanning) {
    pregnancyConsiderations =
      'Pregnancy: acetaminophen is safest acute therapy. ' +
      'Avoid NSAIDs (3rd trimester — premature ductus arteriosus closure). ' +
      'Triptans: limited data, generally avoided especially in 1st trimester. ' +
      'Preventive: magnesium glycinate 400mg/day is safest. Propranolol with OB guidance. ' +
      'CGRP mAbs: insufficient safety data — hold during pregnancy and breastfeeding.';
  }

  if (nextSteps.length === 0) {
    nextSteps.push(
      'Headache diary for 4–8 weeks to characterize frequency and triggers',
      'Review acute medication use (days/month) to screen for MOH',
      'Assess disability with MIDAS or HIT-6 questionnaire',
      'Neuroimaging only if red flag features present (thunderclap, new pattern, focal deficits)'
    );
  }

  const rationale =
    `Migraine subtype: ${input.migraineSubtype}. ` +
    `Frequency: ${input.frequency} (${input.headacheDaysPerMonth} days/month). ` +
    `Acute therapy response: ${input.acuteTherapyResponse.replace(/_/g, ' ')}. ` +
    `Preventive history: ${input.preventiveHistory.replace(/_/g, ' ')}. ` +
    `MOH: ${input.hasMOH ? 'Yes' : 'No'} (${input.acuteMedicationDaysPerMonth} acute med days/month). ` +
    `CV disease: ${input.hasCardiovascularDisease ? 'Yes' : 'No'}.`;

  return {
    primaryRecommendation:
      needsPreventive
        ? `${input.frequency === 'chronic' ? 'Chronic' : 'High-frequency'} migraine: preventive therapy indicated. ${input.preventiveHistory === 'failed_2plus_preventives' ? 'CGRP mAb recommended after ≥2 oral preventive failures.' : 'First-line oral preventive recommended.'}`
        : 'Episodic migraine: optimize acute therapy. Preventive therapy not currently indicated.',
    acuteTherapy,
    preventiveTherapy,
    recommendedAgents,
    agentsToAvoid,
    mohManagement,
    urgentFlags,
    pregnancyConsiderations,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'Ailani J, et al. The American Headache Society Consensus Statement: Update on integrating new migraine treatments into clinical practice. Headache. 2021;61(7):1021-1039.',
        pmid: '34160823',
        url: 'https://pubmed.ncbi.nlm.nih.gov/34160823/',
      },
      {
        citation: 'Silberstein SD, et al. Evidence-based guideline update: Pharmacologic treatment for episodic migraine prevention in adults. Neurology. 2012;78(17):1337-1345.',
        pmid: '22529202',
        url: 'https://pubmed.ncbi.nlm.nih.gov/22529202/',
      },
      {
        citation: 'Dodick DW, et al. ARISE: A Phase 3 randomized trial of erenumab for episodic migraine. Cephalalgia. 2018;38(6):1026-1037.',
        pmid: '29471679',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29471679/',
      },
      {
        citation: 'Goadsby PJ, et al. A Controlled Trial of Erenumab for Episodic Migraine. N Engl J Med. 2017;377(22):2123-2132.',
        pmid: '29171821',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29171821/',
      },
      {
        citation: 'AAN/AHS 2025 CGRP Guideline Update. American Academy of Neurology.',
        url: 'https://www.aan.com/Guidelines/',
      },
      {
        citation: 'Diener HC, et al. Medication-overuse headache: a worldwide problem. Lancet Neurol. 2019;18(3):291-302.',
        pmid: '30773457',
        url: 'https://pubmed.ncbi.nlm.nih.gov/30773457/',
      },
    ],
  };
}

export function getMigraineFrequencyColor(frequency: MigraineFrequency): string {
  switch (frequency) {
    case 'low': return 'text-green-700 bg-green-50 border-green-200';
    case 'moderate': return 'text-yellow-700 bg-yellow-50 border-yellow-200';
    case 'high': return 'text-orange-700 bg-orange-50 border-orange-200';
    case 'chronic': return 'text-red-700 bg-red-50 border-red-200';
  }
}
